let timer = null;
let isRunning = false;
let secondsLeft = 25 * 60; // 25 minutes in seconds
let isBreakTime = false;
let workMinutes = 25;
let breakMinutes = 5;
let notificationTimeout = null;

const timerDisplay = document.getElementById('timer');
const startBtn = document.getElementById('startBtn');
const stopBtn = document.getElementById('stopBtn');
const resetBtn = document.getElementById('resetBtn');
const countDisplay = document.getElementById('count');
const notification = document.getElementById('notification');
const workMinutesInput = document.getElementById('workMinutes');
const breakMinutesInput = document.getElementById('breakMinutes');
const saveSettingsBtn = document.getElementById('saveSettingsBtn');

async function parseResponse(response) {
    let data = null;
    try {
        data = await response.json();
    } catch (e) {
        data = null;
    }
    if (!response.ok) {
        const message = data && data.error ? data.error : ('HTTP ' + response.status);
        throw new Error(message);
    }
    if (data === null) {
        throw new Error('伺服器回應格式錯誤');
    }
    return data;
}

function updateTimerDisplay() {
    const minutes = Math.floor(secondsLeft / 60);
    const seconds = secondsLeft % 60;
    timerDisplay.textContent = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
}

function startTimer() {
    if (isRunning) return;

    isRunning = true;
    timer = setInterval(() => {
        secondsLeft--;
        updateTimerDisplay();

        if (secondsLeft <= 0) {
            clearInterval(timer);
            isRunning = false;

            if (!isBreakTime) {
                // Pomodoro time finished, start break
                isBreakTime = true;
                secondsLeft = breakMinutes * 60; // Use custom break time
                showNotification('休息時間到！');
                updateTimerDisplay();
                startTimer(); // Auto-start break timer
            } else {
                // Break time finished, increment count and start new pomodoro
                isBreakTime = false;
                secondsLeft = workMinutes * 60; // Use custom work time
                incrementCount();
                showNotification('新的番茄鐘開始！');
                updateTimerDisplay();
            }
        }
    }, 1000);
}

function stopTimer() {
    if (!isRunning) return;

    clearInterval(timer);
    isRunning = false;
}

function resetTimer() {
    stopTimer();
    secondsLeft = isBreakTime ? breakMinutes * 60 : workMinutes * 60; // Reset to current mode
    updateTimerDisplay();
}

function incrementCount() {
    fetch('api/count/increment', { method: 'POST' })
        .then(parseResponse)
        .then(data => {
            countDisplay.textContent = data.count;
        })
        .catch(error => {
            showNotification('更新完成次數時發生錯誤：' + error.message);
        });
}

function getCount() {
    fetch('api/count')
        .then(parseResponse)
        .then(data => {
            countDisplay.textContent = data.count;
        })
        .catch(error => {
            showNotification('讀取完成次數時發生錯誤：' + error.message);
        });
}

function saveSettings() {
    const newWorkMinutes = parseInt(workMinutesInput.value, 10);
    const newBreakMinutes = parseInt(breakMinutesInput.value, 10);

    if (isNaN(newWorkMinutes) || isNaN(newBreakMinutes) || newWorkMinutes < 1 || newBreakMinutes < 1) {
        showNotification('請輸入有效的分鐘數');
        return;
    }

    workMinutes = newWorkMinutes;
    breakMinutes = newBreakMinutes;

    // Update the timer display to reflect new settings
    if (!isRunning) {
        secondsLeft = isBreakTime ? breakMinutes * 60 : workMinutes * 60;
        updateTimerDisplay();
    }

    // Send settings to backend
    fetch('api/settings', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            work_minutes: newWorkMinutes,
            break_minutes: newBreakMinutes
        })
    })
    .then(parseResponse)
    .then(data => {
        showNotification('設定已儲存');
    })
    .catch(error => {
        showNotification('儲存設定時發生錯誤：' + error.message);
    });
}

function getSettings() {
    fetch('api/settings')
        .then(parseResponse)
        .then(data => {
            workMinutes = data.work_minutes;
            breakMinutes = data.break_minutes;
            workMinutesInput.value = workMinutes;
            breakMinutesInput.value = breakMinutes;
            if (!isRunning) {
                secondsLeft = isBreakTime ? breakMinutes * 60 : workMinutes * 60;
                updateTimerDisplay();
            }
        })
        .catch(error => {
            showNotification('讀取設定時發生錯誤：' + error.message);
        });
}

function showNotification(message) {
    notification.textContent = message;
    notification.style.display = 'block';

    if (notificationTimeout) {
        clearTimeout(notificationTimeout);
    }
    notificationTimeout = setTimeout(() => {
        notification.style.display = 'none';
    }, 4000);
}

// Initialize the display
getCount();
getSettings();
updateTimerDisplay();

startBtn.addEventListener('click', startTimer);
stopBtn.addEventListener('click', stopTimer);
resetBtn.addEventListener('click', resetTimer);
saveSettingsBtn.addEventListener('click', saveSettings);

